import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
  JxBadgeTone,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'over' | 'archived';

interface Project {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const STATUS_LABEL: Record<ProjectStatus, string> = {
  active: 'Активен',
  warning: 'Близко к лимиту',
  over: 'Превышен',
  archived: 'Архив',
};

const STATUS_TONE: Record<ProjectStatus, JxBadgeTone> = {
  active: 'success',
  warning: 'warning',
  over: 'danger',
  archived: 'default',
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Мобильное приложение', quotaPercent: 42, status: 'active' },
  { id: 'p2', name: 'Внутренний портал', quotaPercent: 88, status: 'warning' },
  { id: 'p3', name: 'Аналитика продаж', quotaPercent: 63, status: 'active' },
  { id: 'p4', name: 'Маркетинговый сайт', quotaPercent: 100, status: 'over' },
  { id: 'p5', name: 'Старый бэкенд', quotaPercent: 12, status: 'archived' },
  { id: 'p6', name: 'Платёжный шлюз', quotaPercent: 76, status: 'warning' },
  { id: 'p7', name: 'Служба поддержки', quotaPercent: 34, status: 'active' },
  { id: 'p8', name: 'ML-пайплайн', quotaPercent: 95, status: 'over' },
  { id: 'p9', name: 'Документация', quotaPercent: 8, status: 'archived' },
  { id: 'p10', name: 'CRM-интеграция', quotaPercent: 57, status: 'active' },
  { id: 'p11', name: 'Биллинг', quotaPercent: 81, status: 'warning' },
  { id: 'p12', name: 'Логистика', quotaPercent: 22, status: 'active' },
];

const STATUS_ORDER: ProjectStatus[] = ['active', 'warning', 'over', 'archived'];
const PAGE_SIZE = 5;

export default function ProjectQuotaPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses([]);
    setPage(1);
  };

  const filteredProjects = useMemo(() => {
    if (activeStatuses.length === 0) return PROJECTS;
    return PROJECTS.filter((project) => activeStatuses.includes(project.status));
  }, [activeStatuses]);

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const visibleProjects = filteredProjects.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r-lg)',
        padding: 'var(--jx-r-lg)',
        background: 'var(--jx-surface)',
        borderRadius: 'var(--jx-r-xl)',
        boxShadow: 'var(--jx-shadow-sm)',
        maxWidth: '640px',
      }}
    >
      <div>
        <h2
          style={{
            margin: 0,
            marginBottom: 'var(--jx-r-sm)',
            fontFamily: 'var(--jx-font-display)',
            color: 'var(--jx-text)',
          }}
        >
          Расход по проектам
        </h2>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-r-sm)' }}>
          {STATUS_ORDER.map((status) => (
            <JxChip
              key={status}
              active={activeStatuses.includes(status)}
              removable={activeStatuses.includes(status)}
              onClick={() => toggleStatus(status)}
              onRemove={() => toggleStatus(status)}
            >
              {STATUS_LABEL[status]}
            </JxChip>
          ))}
        </div>
      </div>

      {visibleProjects.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="По выбранным статусам нет ни одного проекта. Сбросьте фильтры, чтобы увидеть весь список."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}>
            {visibleProjects.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 'var(--jx-r)',
                  padding: 'var(--jx-r)',
                  background: 'var(--jx-surface-2)',
                  borderRadius: 'var(--jx-r-lg)',
                  border: '1px solid var(--jx-border)',
                }}
              >
                <span
                  style={{
                    color: 'var(--jx-text)',
                    fontFamily: 'var(--jx-font-sans)',
                    flex: 1,
                    minWidth: 0,
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                  }}
                >
                  {project.name}
                </span>
                <JxProgressCircle value={project.quotaPercent} showValue />
                <JxBadge tone={STATUS_TONE[project.status]} dot>
                  {STATUS_LABEL[project.status]}
                </JxBadge>
              </div>
            ))}
          </div>

          {pageCount > 1 && (
            <JxPagination total={pageCount} page={page} onPageChange={setPage} />
          )}
        </>
      )}
    </div>
  );
}

